package mx.gob.sedesol.basegestor.gestionescolar.v2;
import static org.testng.Assert.*; import java.util.Date; import org.testng.annotations.Test; import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.*; import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;
/** F5F: orquestación final CTR-01/RN-6.1 en sombra. */
public class EvaluacionCurricularV2Fase5FTest {private final EvaluacionCurricularV2ServiceImpl s=new EvaluacionCurricularV2ServiceImpl();
 @Test public void noAplica(){ContextoEvaluacionCurricularV2DTO z=c();z.setSemestreObjetivo(3);assertEquals(x(z).getDecisionGlobalRn61(),EstadoDecisionControlAvanceRn61V2.NO_APLICA);}
 @Test public void ordinario(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().clear();for(int i=1;i<5;i++)z.getUnidades().add(u(i,i,EstadoUnidadCurricularV2.ACREDITADA));assertEquals(x(z).getDecisionGlobalRn61(),EstadoDecisionControlAvanceRn61V2.ACCESO_ORDINARIO_PROCEDE_EN_SOMBRA);}
 @Test public void rn64Prevalece(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().add(r(2,2));z.getUnidades().add(r(3,3));z.getUnidades().add(r(4,4));assertEquals(x(z).getDecisionGlobalRn61(),EstadoDecisionControlAvanceRn61V2.AVANCE_CONDICIONADO_NO_PROCEDE);}
 @Test public void mixtoPorUd(){ContextoEvaluacionCurricularV2DTO z=c();UnidadEvaluacionCurricularV2DTO a=u(50,5,EstadoUnidadCurricularV2.NO_CURSADA);a.setSeriacionDirectaConocida(true);z.getUnidades().add(a);z.getUnidades().add(u(51,5,EstadoUnidadCurricularV2.NO_CURSADA));String q=x(z).getDecisionesPorUdQuintoRn61().toString();assertTrue(q.contains("50:NO_PROCEDE_POR_SERIACION_DIRECTA"));assertTrue(q.contains("51:AVANCE_CONDICIONADO_PROCEDE_EN_SOMBRA"));}
 @Test public void sinEfecto(){assertFalse(s.evaluarSombra(c()).getEfectosProductivosAplicados());}
 private EvaluacionCargaAcademicaV2DTO x(ContextoEvaluacionCurricularV2DTO z){return s.evaluarSombra(z).getEvaluacionCargaAcademica();}private ContextoEvaluacionCurricularV2DTO c(){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setIdPlan(1L);z.setPeriodoNormativo("2027-1");z.setSemestreObjetivo(5);z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0));z.setActividadAcademicaComprobada(true);z.setPermanenciaDentroLimiteComprobada(true);z.setSeriacionComprobada(true);z.setEstructuraProgramaEducativoComprobada(true);z.setSancionImpedimentoConocida(true);z.setSancionImpedimentoRegistrada(false);z.setRestriccionPeNormativaConocida(true);z.setRestriccionPeNormativaImpeditiva(false);z.getUnidades().add(r(1,1));return z;}private UnidadEvaluacionCurricularV2DTO r(long i,int se){UnidadEvaluacionCurricularV2DTO u=u(i,se,EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(true);u.setReprobacionPeriodoPrevioConocida(true);return u;}private UnidadEvaluacionCurricularV2DTO u(long i,int se,EstadoUnidadCurricularV2 e){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("U"+i);u.setTipoUd("Obligatoria");u.setSemestre(se);u.setEstado(e);u.setOfertada(true);u.setGrupoActivoConocido(true);u.setCupoDisponibleConocido(true);return u;}}
